  function lockedIslandAt(p){if(state.level<ISLAND_LEVELS.cedar&&p.y<-90&&p.x>600)return{name:'Cedar Isle',level:ISLAND_LEVELS.cedar};if(state.level<ISLAND_LEVELS.palm&&p.x<0&&p.y<320)return{name:'Palm Key',level:ISLAND_LEVELS.palm};if(state.level<ISLAND_LEVELS.coffee&&p.x<0&&p.y>=280)return{name:'Coffee Key',level:ISLAND_LEVELS.coffee};if(state.level<ISLAND_LEVELS.mainland&&p.x>=0&&p.y<400)return{name:'Emerald Bay 본섬',level:ISLAND_LEVELS.mainland};return null}
  function unlockLevel(s){return s.unlock||1}
  function card(s){const next=s.built?Math.round(s.cost*Math.pow(1.55,s.level)):s.cost,unlock=unlockLevel(s);return `<article class="build-card ${state.level<unlock?'locked':''}"><span class="card-art">${s.icon}</span><h3>${s.name}</h3><p>${state.level<unlock?`섬 레벨 ${unlock}에 개방`:s.built?`Lv.${s.level} · ${fmt(facilityIncome(s))} / ${facilityTime(s).toFixed(1)}초`:`생산 시설을 건설합니다.`}</p><button data-build="${s.id}" data-purchase-cost="${next}" data-max="${state.level<unlock}" ${state.coins<next||state.level<unlock?'disabled':''}>${state.level<unlock?'🔒 LOCKED':`${s.built?'UPGRADE':'BUILD'} · ● ${fmt(next)}`}</button></article>`}
  function bindBuildButtons(){document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>build(b.dataset.build))}
